    return sorted(k for k, v in d.items() if v == max_val)

def merge_min_all_keys(a, b):
    result = dict(a)
    for k, v in b.items():
        if k in result:
            if v < result[k]:
                result[k] = v
        else:
            result[k] = v
    return result

def tokenize_mixed_alnum(s):
    tokens = []
    current = []
    current_type = None
    for ch in s:
        if ch.isalpha():
            t = 'alpha'
        elif ch.isdigit():
            t = 'digit'
        else:
            t = None
        if t is None:
            if current:
                tokens.append(''.join(current))
                current = []
                current_type = None
            continue
        if t == current_type:
            current.append(ch)
        else:
            if current:
                tokens.append(''.join(current))
            current = [ch]
            current_type = t
    if current:
        tokens.append(''.join(current))
    return tokens

from collections import Counter

def keys_with_unique_values(d):
    counts = Counter(d.values())
    return sorted(k for k, v in d.items() if counts[v] == 1)

def is_valid_time_string(s):
    if len(s) != 8:
        return False
    if s[2] != ':' or s[5] != ':':
        return False
    h, m, sec = s[0:2], s[3:5], s[6:8]
    if not (h.isdigit() and m.isdigit() and sec.isdigit()):
        return False
    if not (len(h) == 2 and len(m) == 2 and len(sec) == 2):
        return False
    h_i, m_i, s_i = int(h), int(m), int(sec)
    return 0 <= h_i <= 23 and 0 <= m_i <= 59 and 0 <= s_i <= 59

def digit_product(n):
    product = 1
    for ch in str(abs(n)):
        product *= int(ch)
    return product

def count_pairs_summing_to(nums, target):
    count = 0
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] + nums[j] == target:
                count += 1
    return count

def split_keep_delimiters(s, delims):
    delim_set = set(delims)
    tokens = []
    current = []
    for ch in s:
        if ch in delim_set:
            if current:
                tokens.append(''.join(current))
                current = []
            tokens.append(ch)
        else:
            current.append(ch)
    if current:
        tokens.append(''.join(current))
    return tokens

import calendar
from datetime import date

def year_progress_percentage(year, month, day):
    day_of_year = date(year, month, day).timetuple().tm_yday
    days_in_year = 366 if calendar.isleap(year) else 365
    return round(day_of_year / days_in_year * 100, 2)

def truncate_column(s, width):
    if len(s) > width:
        return s[:width]
    return s.ljust(width)

def dict_diff(a, b):
    added = sorted(k for k in b if k not in a)
    removed = sorted(k for k in a if k not in b)
    changed = {k: (a[k], b[k]) for k in a if k in b and a[k] != b[k]}
    return {'added': added, 'removed': removed, 'changed': changed}

def bottom_k_elements(lst, k):
    if k <= 0:
        return []
    return sorted(lst)[:k]

def difference_largest_second_largest(lst):
    if len(lst) < 2:
        return None
    s = sorted(lst, reverse=True)
    return s[0] - s[1]

def is_time_between(check_hhmm, start_hhmm, end_hhmm):
    def to_minutes(t):
        h, m = t.split(':')
        return int(h) * 60 + int(m)
    c = to_minutes(check_hhmm)
    s = to_minutes(start_hhmm)
    e = to_minutes(end_hhmm)
    if e <= s:
        e += 24 * 60
        if c < s:
            c += 24 * 60
    return s <= c < e

def count_distinct_words_case_insensitive(s):
    words = s.split()
    return len(set(w.lower() for w in words))

def oxford_join_quoted(items):
    quoted = ['"' + item + '"' for item in items]
    if not quoted:
        return ''
    if len(quoted) == 1:
        return quoted[0]
    if len(quoted) == 2:
        return quoted[0] + ' and ' + quoted[1]
    return ', '.join(quoted[:-1]) + ', and ' + quoted[-1]
